import numpy as np

def transform(grid):
    result = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Find colors to fill (excluding 0)
    colors = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                colors.add(grid[r][c])

    for color in colors:
        interior_color = 2 if color == 1 else 7

        # Find frames of this color
        for c in range(w):
            if grid[0][c] != color:
                continue

            # Expand right
            right = c
            while right + 1 < w and grid[0][right+1] == color:
                right += 1

            if right <= c:
                continue

            # Expand down
            frame = all(grid[r][cc] == color for r in range(h) for cc in range(c, right+1))
            if not frame:
                continue

            h_frame = w_frame = 0
            for r in range(h):
                if all(grid[r][cc] == color for cc in range(c, right+1)):
                    h_frame = r + 1
                else:
                    break

            if h_frame < 3:
                continue

            # Check if this is a frame
            is_frame = True
            for r in range(h_frame):
                if not (grid[r][c] == color and grid[r][right] == color):
                    is_frame = False
                    break

            if not is_frame:
                continue

            # Check left column for non-edge rows
            for r in range(1, h_frame-1):
                if not (grid[r][c] == color and grid[r][right] == color):
                    is_frame = False
                    break

            if is_frame:
                # Fill interior
                for r in range(1, h_frame-1):
                    for cc in range(c+1, right):
                        result[r][cc] = interior_color

    return result

